suppressPackageStartupMessages({library(ggplot2);library(ggrastr);library(patchwork)})
md<-qread(out('00_audit/cell_metadata.qs'));can<-fread(out('08_review/FINAL_CANDIDATES.tsv'));met<-fread(out('02_coverage/all_clusters_two_high.tsv'));base<-fread(out('02_coverage/old_baselines.tsv'));cov<-fread(out('02_coverage/candidate_source_coverage.tsv'));dots<-fread(out('08_review/display_marker_DotPlot_data.tsv'));if(!nrow(dots))dots<-data.table(scope=character(),candidate_id=character(),gene_id=character(),comparison_id=character(),control_type=character(),n_samples=integer(),expr_left=numeric(),expr_right=numeric(),det_left=numeric(),det_right=numeric());sm<-data.table(sample=sort(unique(md$sample)));sm[,sample_code:=sprintf('S%02d',.I)];wt(merge(sm,unique(md[,.(sample,dataset,source)]),by='sample'),'07_figures/sample_display_key.tsv');md<-merge(md,sm,by='sample',sort=FALSE);scopes<-c('ALL',sort(unique(md$dataset)));cols<-c(FULL_RAW='#BB3754',FULL_Z='#3B528B');idx<-list()
th<-theme_classic(base_size=9)+theme(plot.background=element_rect(fill='transparent',colour=NA),panel.background=element_rect(fill='transparent',colour=NA),legend.background=element_rect(fill='transparent',colour=NA),strip.background=element_blank(),strip.text=element_text(size=8))
savep<-function(p,n,data,w=12,h=8,caption=''){fn<-out(paste0('07_figures/',n));ggsave(paste0(fn,'.pdf'),p,width=w,height=h,bg='transparent',limitsize=FALSE);ggsave(paste0(fn,'.png'),p,width=w,height=h,dpi=300,bg='transparent',limitsize=FALSE);wt(data,paste0('07_figures/',n,'_plotdata.tsv.gz'));idx[[length(idx)+1L]]<<-data.table(figure=n,pdf=paste0(fn,'.pdf'),png=paste0(fn,'.png'),plot_data=paste0(fn,'_plotdata.tsv.gz'),caption=caption);wt(rbindlist(idx),'07_figures/figure_index.tsv');logmsg('Figure',n)}
placeholder<-function(msg)ggplot()+annotate('text',x=0,y=0,label=msg,size=3)+theme_void()+th
# Precision/recall frontiers: all single clusters, no unions. Candidate annotations only.
for(h in c('NMF','UCell')){d<-met[high==h];candids<-can$result_id;d[,winner:=result_id%in%candids];b<-base[baseline=='C8'&high==h];p<-ggplot(d,aes(precision,recall,color=representation))+geom_hline(yintercept=c(.5,.6,.7),linetype=3,color='grey75')+geom_vline(xintercept=c(.5,.6,.7),linetype=3,color='grey75')+geom_point(aes(alpha=winner),size=1.5)+geom_text(data=d[winner==TRUE],aes(label=sprintf('%.2f',resolution)),size=2.4,vjust=-.6,check_overlap=FALSE)+geom_point(data=b,aes(precision,recall),inherit.aes=FALSE,shape=4,size=3,color='black')+scale_color_manual(values=cols)+scale_alpha_manual(values=c('FALSE'=.25,'TRUE'=1),guide='none')+facet_wrap(~representation)+coord_cartesian(xlim=c(0,1),ylim=c(0,1))+labs(x='Precision',y='Recall',color=NULL)+th;savep(p,paste0('ALL__',h,'__PR_all_clusters'),d,12,6,'Fixed global high. Numbers are resolutions of partition champions; black cross is old C8. Lines .50/.60/.70 are visual references, not biological thresholds.')}
# Every candidate/dataset, pooled source counts. Dataset points do not affect ranking.
for(ds in scopes[scopes!='ALL']){d<-merge(cov[field=='dataset'&level==ds],can[,.(candidate_id,representation,resolution)],by='candidate_id');p<-ggplot(d,aes(precision,recall,color=representation))+geom_point(size=1.8,na.rm=TRUE)+facet_wrap(~high)+scale_color_manual(values=cols)+coord_cartesian(xlim=c(0,1),ylim=c(0,1))+labs(x='Dataset precision',y='Dataset recall',color=NULL)+th;savep(p,paste0(ds,'__candidate_PR'),d,10,5,'Full dataset denominator; candidates were fixed using FULL. NA precision/recall stays NA; zero recall retained.')}
# All candidates in compact sample coverage and composition panels.
for(ds in scopes){samp<-if(ds=='ALL')sm$sample else unique(md[dataset==ds,sample]);d<-merge(cov[field=='sample'&level%in%samp],sm,by.x='level',by.y='sample');d<-melt(d,id.vars=c('candidate_id','high','sample_code'),measure.vars=c('precision','recall'),variable.name='metric',value.name='value');p<-ggplot(d,aes(sample_code,candidate_id))+geom_tile(data=d[is.na(value)],fill='grey75')+geom_tile(data=d[is.finite(value)&value==0],fill='black')+geom_tile(data=d[is.finite(value)&value>0],aes(fill=value))+scale_fill_viridis_c(option='plasma',limits=c(0,1),name='Fraction')+facet_grid(high~metric)+labs(x='All source samples (see key)',y='Frozen candidate ID')+th+theme(axis.text.x=element_text(angle=90,hjust=1,size=6),axis.text.y=element_text(size=6));savep(p,paste0(ds,'__sample_precision_recall'),d,15,15,'Sample high>0/candidate=0 gives recall0; high=0 gives recallNA; candidate=0 gives precisionNA. Zero black, NA grey; no >=30 filter.')
 ss<-merge(cov[field=='sample'&high=='NMF'&level%in%samp],unique(md[,.(sample,source)]),by.x='level',by.y='sample');ss<-ss[,.(n_candidate=sum(n_candidate)),by=.(candidate_id,source)];ss[,fraction:=if(sum(n_candidate))n_candidate/sum(n_candidate)else NA_real_,by=candidate_id];p<-ggplot(ss,aes(candidate_id,fraction,fill=source))+geom_col(na.rm=TRUE)+labs(x='Candidate (separate overlapping partitions)',y='Source fraction within candidate')+th+theme(axis.text.x=element_text(angle=90,hjust=1,size=6));savep(p,paste0(ds,'__candidate_source_composition'),ss,15,5,'Each candidate is a separate partition-defined group; bars must not be added across candidates. All zero candidates retained as NA bars.')
}
# DotPlot panels, max3 display genes/candidate. Full up-to20 shortlist is in review tables.
mx<-if(nrow(dots))max(c(dots$expr_left,dots$expr_right))else 1
for(ds in scopes)for(rep in reps){d<-dots[scope==ds&candidate_id%in%can[representation==rep,candidate_id]];if(nrow(d)){d<-rbind(d[,.(candidate_id,gene_id,comparison_id,control_type,n_samples,group='Left',expression=expr_left,detection=det_left)],d[,.(candidate_id,gene_id,comparison_id,control_type,n_samples,group='Right',expression=expr_right,detection=det_right)]);d[,column:=paste(control_type,group,sep=':')];p<-ggplot(d,aes(column,gene_id,size=detection))+geom_point(data=d[expression>0],aes(color=expression))+geom_point(data=d[expression==0],color='black')+scale_color_viridis_c(option='plasma',limits=c(0,mx),name='Sample-equal RNA mean')+scale_size_continuous(limits=c(0,1),range=c(.3,4),name='Sample-equal detection')+facet_wrap(~candidate_id,ncol=4,scales='free')+labs(x=NULL,y=NULL)+th+theme(panel.grid=element_blank(),axis.text.x=element_text(angle=90,hjust=1,size=6),axis.text.y=element_text(size=7));savep(p,paste0(ds,'__',rep,'__candidate_marker_DotPlot'),d,17,max(5,ceiling(uniqueN(d$candidate_id)/4)*2.7),'Paired eligible samples only; RNA mean is ordinary log-normalized expression, not usage. n_samples retained in plot data. Missing candidate/comparison panels mean no display markers or no eligible source pairs; consult status table.')}else savep(placeholder('No eligible paired display-marker data; see model status'),paste0(ds,'__',rep,'__candidate_marker_DotPlot'),data.table(scope=ds,representation=rep,status='no_eligible_display_data'),10,3)}
# Shared fixed embeddings, exact ID alignment. One continuous base per branch/dataset; reuse for all resolutions.
em<-list(FULL_RAW=qread(file.path(old,'04_full_raw/umap.qs')),FULL_Z=qread(file.path(old,'03_full_z/umap.qs')));if(file.exists(out('00_audit/original_RNA_umap.qs')))em$RNA<-qread(out('00_audit/original_RNA_umap.qs'))
md[,usage_log1p:=log1p(usage10)];limits<-list(ucell10=range(md$ucell10),usage_log1p=range(md$usage_log1p));wt(data.table(metric=c('ucell10','usage_log1p','RNA_mean'),lower=c(limits$ucell10[1],limits$usage_log1p[1],0),upper=c(limits$ucell10[2],limits$usage_log1p[2],mx)),'07_figures/color_limits.tsv');set.seed(42);orderids<-sample(md$cell_id)
for(rep in names(em)){e<-em[[rep]];d<-copy(md);stopifnot(setequal(rownames(e),d$cell_id));d[,`:=`(x=e[cell_id,1],y=e[cell_id,2])];d<-d[match(orderids,cell_id)];xl<-range(d$x);yl<-range(d$y);wt(d[,.(cell_id,dataset,sample,x,y,ucell10,usage_log1p)],paste0('07_figures/',rep,'_shared_embedding.tsv.gz'))
 for(ds in scopes){dd<-if(ds=='ALL')d else d[dataset==ds];pp<-lapply(names(limits),function(v)ggplot(dd,aes(x,y))+geom_point_rast(data=dd[get(v)==0],color='black',size=.08,raster.dpi=300)+geom_point_rast(data=dd[get(v)>0],aes(color=.data[[v]]),size=.08,raster.dpi=300)+scale_color_viridis_c(option='plasma',limits=limits[[v]],name=if(v=='ucell10')'MP10 UCell raw'else'log1p MP10 usage raw')+coord_cartesian(xlim=xl,ylim=yl)+labs(x='UMAP 1',y='UMAP 2')+th+theme(axis.text=element_blank(),axis.ticks=element_blank()));p<-wrap_plots(pp,ncol=2)+plot_annotation(theme=theme(plot.background=element_rect(fill='transparent',colour=NA)));savep(p,paste0(ds,'__',rep,'__shared_continuous'),data.table(source=paste0(rep,'_shared_embedding.tsv.gz'),dataset=ds,n_cells=nrow(dd)),11,5,'Frozen embedding and FULL continuous limits; shared across every resolution. Source table contains actual per-cell plot data.')
 # Candidate highlight contact sheet, global positions, no embedding recomputation.
 cc<-if(rep=='RNA')can[recommended==TRUE]else can[representation==rep];pp<-list();for(i in 1:nrow(cc)){c<-cc[i];lab<-qread(out(paste0('01_partitions/',c$partition,'.qs')));aa<-copy(dd);aa[,selected:=lab$cluster[match(cell_id,lab$cell_id)]==c$cluster];pp[[i]]<-ggplot(aa,aes(x,y))+geom_point_rast(data=aa[selected==FALSE],color='grey88',size=.06,raster.dpi=200)+geom_point_rast(data=aa[selected==TRUE],color=cols[c$representation],size=.09,raster.dpi=300)+coord_cartesian(xlim=xl,ylim=yl)+labs(x=c$candidate_id,y=NULL)+th+theme(axis.text=element_blank(),axis.ticks=element_blank())};p<-wrap_plots(pp,ncol=if(rep=='RNA')2 else 4)+plot_annotation(theme=theme(plot.background=element_rect(fill='transparent',colour=NA)));savep(p,paste0(ds,'__',rep,'__candidate_highlights'),cc[,.(candidate_id,partition,cluster,n_cells)],if(rep=='RNA')10 else 16,if(rep=='RNA')5 else max(5,ceiling(nrow(cc)/4)*3),'Actual coordinates are in branch_shared_embedding.tsv.gz; highlight IDs resolve through 01_partitions and candidates_preDE. Full unfiltered source shown; zero-candidate panels retained.')
 }}
# Clustree-style all-member flows. Node y positions use FULL cluster sizes, not UMAP.
fl<-fread(out('06_stability/adjacent_cluster_flows.tsv'));sz<-fread(out('01_partitions/all_cluster_sizes.tsv'));sz[,x:=match(resolution,resolutions)];setorder(sz,representation,x,cluster_numeric);sz[,y:=(cumsum(n_cells)-n_cells/2)/sum(n_cells),by=partition];a<-merge(fl,sz[,.(partition_from=partition,from=cluster,x,y,n_cells)],by=c('partition_from','from'));a<-merge(a,sz[,.(partition_to=partition,to=cluster,xend=x,yend=y,representation)],by=c('partition_to','to'));p<-ggplot()+geom_segment(data=a,aes(x=x,y=y,xend=xend,yend=yend,linewidth=N/123699),alpha=.2,color='grey40')+geom_point(data=sz,aes(x,y,size=n_cells,color=representation))+geom_text(data=sz,aes(x,y,label=cluster),size=1.8,nudge_y=.008)+scale_color_manual(values=cols)+scale_linewidth_continuous(range=c(.05,4),guide='none')+scale_size_continuous(range=c(.7,6),name='Cluster cells')+scale_x_continuous(breaks=1:12,labels=sprintf('%.2f',resolutions))+facet_wrap(~representation,ncol=1)+labs(x='Resolution',y='FULL membership flow')+th;savep(p,'ALL__adjacent_resolution_member_flows',a,17,12,'All nonzero adjacent overlaps, no merging/reclustering; vertical positions are cumulative FULL cluster sizes, not biological distances.')
j<-fread(out('06_stability/candidate_Jaccard.tsv'));p<-ggplot(j[type=='RAW_Z'],aes(candidate_A,candidate_B,fill=Jaccard))+geom_tile()+scale_fill_viridis_c(option='plasma',limits=c(0,1))+labs(x='RAW candidate',y='Z candidate')+th+theme(axis.text.x=element_text(angle=90,hjust=1,size=6));savep(p,'ALL__RAW_Z_candidate_Jaccard',j[type=='RAW_Z'],12,10,'Actual shared cell IDs; cluster numbers are not assumed comparable.')
wt(rbindlist(idx),'07_figures/figure_index.tsv');writeLines('complete',out('07_figures/COMPLETE'));logmsg('Figures complete')
